"""PL-01 step 3: put every ticker on one calendar."""

from __future__ import annotations

from collections.abc import Sequence

from mdata.types import GapError, Prices, RawRow


def align_calendar(rows: Sequence[RawRow], *, max_gap: int = 5) -> Prices:
    """Every date any ticker trades, from the first date all have a close; gaps take the previous close.

    A ticker missing more than `max_gap` calendar dates in a row raises `GapError` naming it.
    """
    by_ticker: dict[str, dict[str, float]] = {}
    for row in rows:
        if row.close is not None:
            by_ticker.setdefault(row.ticker, {})[row.date] = row.close
    tickers = tuple(sorted(by_ticker))
    start = max((min(series) for series in by_ticker.values()), default="")
    dates = tuple(sorted({date for series in by_ticker.values() for date in series if date >= start}))
    closes = {ticker: _fill(ticker, by_ticker[ticker], dates, max_gap) for ticker in tickers}
    return Prices(dates=dates, tickers=tickers, closes=closes)


def _fill(ticker: str, series: dict[str, float], dates: tuple[str, ...], max_gap: int) -> tuple[float, ...]:
    """One close per calendar date, each missing date taking the previous close."""
    filled: list[float] = []
    missing = 0
    for date in dates:
        if date in series:
            filled.append(series[date])
            missing = 0
            continue
        missing += 1
        if missing > max_gap:
            raise GapError(f"{ticker}: more than {max_gap} dates in a row missing, from before {date}")
        filled.append(filled[-1])
    return tuple(filled)

